XM25 N2 N1 N2 VDD sky130_fd_pr__pfet_01v8 l={L_xm25} w={W_xm25}

VVDD VDD 0 1.8
VLABEL_NET_1 LABEL_NET_1 0 0.9
VLABEL_NET_2 LABEL_NET_2 0 0.9
VLABEL_NET_4 LABEL_NET_4 0 0.9

* Input sources
V_INP LABEL_NET_0 0 dc 0.9 ac 1 pulse(0.4 1.4 10u 1u 1u 1m 2m)

* Feedback network for AC open-loop / DC closed-loop
L_fb N1 LABEL_NET_5 1T
C_ac LABEL_NET_5 0 1T

* Load capacitor
C_load N1 0 1p

.control
  * DC Operating Point
  op
  let power = -i(VVDD) * 1.8
  print power

  * AC Analysis
  ac dec 20 1 1G
  let gain_db = vdb(N1)
  let phase = 180/PI * cph(v(N1))

  meas ac dc_gain find gain_db at=10
  meas ac ugbw when gain_db=0 fall=1
  meas ac phase_margin find phase when gain_db=0 fall=1

  * Transient Analysis
  * Alter feedback to make it a unity gain buffer for transient step
  alter L_fb 1p
  alter C_ac 1f

  tran 1u 2m
  meas tran v_max max v(N1)
  meas tran v_min min v(N1)
  meas tran t_rise trig v(N1) val=0.6 rise=1 targ v(N1) val=1.2 rise=1
  meas tran t_fall trig v(N1) val=1.2 fall=1 targ v(N1) val=0.6 fall=1

  quit
.endc

